insert into public.faqs (id, shop_id, question, answer, keywords, published, sort_order)
values
  ('11111111-1111-4111-8111-000000000001'::uuid, '11111111-1111-4111-8111-111111111111'::uuid, '予約はできますか？', 'はい、ご予約いただけます。下のボタンからネット予約のページへお進みください。', array['予約', 'よやく', 'reserve']::text[], true, 1),
  ('11111111-1111-4111-8111-000000000002'::uuid, '11111111-1111-4111-8111-111111111111'::uuid, '駐車場はありますか？', 'お店の前に2台分あります。満車の場合は近くのコインパーキングをご利用ください。', array['駐車場', 'ちゅうしゃじょう', 'パーキング', 'parking']::text[], true, 2),
  ('11111111-1111-4111-8111-000000000003'::uuid, '11111111-1111-4111-8111-111111111111'::uuid, 'テイクアウトはできますか？', 'できます。日替わり弁当（750円）を11:00〜14:00に販売しています。', array['テイクアウト', '弁当', '持ち帰り']::text[], true, 3),
  ('11111111-1111-4111-8111-000000000004'::uuid, '11111111-1111-4111-8111-111111111111'::uuid, '子ども連れでも利用できますか？', 'はい、ご利用いただけます。子ども用の椅子と取り分け皿をご用意しています。', array['子ども', '子供', '子連れ', 'こども']::text[], true, 4),
  ('11111111-1111-4111-8111-000000000005'::uuid, '11111111-1111-4111-8111-111111111111'::uuid, 'アレルギーへの対応はありますか？', '主な原材料はお伝えできます。詳しくはスタッフにご確認ください。', array['アレルギー', 'アレルゲン']::text[], true, 5),
  ('11111111-1111-4111-8111-000000000006'::uuid, '11111111-1111-4111-8111-111111111111'::uuid, '支払い方法を教えてください', '現金、クレジットカード、主なQRコード決済が使えます。', array['支払い', 'カード', '現金', 'QR']::text[], true, 6),
  ('11111111-1111-4111-8111-000000000007'::uuid, '11111111-1111-4111-8111-111111111111'::uuid, '貸切はできますか？', '15名以上で可能です。日時をご相談ください。', array['貸切', '宴会']::text[], true, 7),
  ('22222222-2222-4222-8222-000000000001'::uuid, '22222222-2222-4222-8222-222222222222'::uuid, '当日予約はできますか？', '空きがあれば可能です。予約ページで空き状況をご確認ください。', array['当日', '予約', '空き']::text[], true, 1),
  ('22222222-2222-4222-8222-000000000002'::uuid, '22222222-2222-4222-8222-222222222222'::uuid, 'カットの所要時間はどれくらいですか？', '約60分です。カラー付きは約2時間が目安です。', array['時間', 'どれくらい', '所要']::text[], true, 2),
  ('22222222-2222-4222-8222-000000000003'::uuid, '22222222-2222-4222-8222-222222222222'::uuid, 'スタッフの指名はできますか？', 'できます。予約ページで担当者を選べます。', array['指名', '担当']::text[], true, 3),
  ('22222222-2222-4222-8222-000000000004'::uuid, '22222222-2222-4222-8222-222222222222'::uuid, 'キャンセルの連絡は？', '前日までに予約ページからお願いします。当日は電話でご連絡ください。', array['キャンセル', '取消']::text[], true, 4),
  ('22222222-2222-4222-8222-000000000005'::uuid, '22222222-2222-4222-8222-222222222222'::uuid, '子どもカットはありますか？', '小学生以下は2,750円です。', array['子ども', '子供', '小学生']::text[], true, 5),
  ('22222222-2222-4222-8222-000000000006'::uuid, '22222222-2222-4222-8222-222222222222'::uuid, '支払い方法を教えてください', '現金、クレジットカード、QRコード決済が使えます。', array['支払い', 'カード', '現金', 'QR']::text[], true, 6),
  ('22222222-2222-4222-8222-000000000007'::uuid, '22222222-2222-4222-8222-222222222222'::uuid, '駐車場はありますか？', '専用駐車場はありません。近くのコインパーキングをご利用ください。', array['駐車場', 'パーキング', 'parking']::text[], true, 7),
  ('33333333-3333-4333-8333-000000000001'::uuid, '33333333-3333-4333-8333-333333333333'::uuid, '初めてですが、何を持っていけばいいですか？', '動きやすい服装でお越しください。着替えの貸し出しもあります。', array['初めて', '持ち物', '服装']::text[], true, 1),
  ('33333333-3333-4333-8333-000000000002'::uuid, '33333333-3333-4333-8333-333333333333'::uuid, '保険は使えますか？', '整体は保険の対象外で、全額自費になります。', array['保険', '自費']::text[], true, 2),
  ('33333333-3333-4333-8333-000000000003'::uuid, '33333333-3333-4333-8333-333333333333'::uuid, 'どれくらいの間隔で通えばいいですか？', '通う間隔は、お一人おひとりのご希望やご都合に合わせて、カウンセリングで施術者とご相談のうえ決めていただけます。', array['頻度', '間隔', '通院']::text[], true, 3),
  ('33333333-3333-4333-8333-000000000004'::uuid, '33333333-3333-4333-8333-333333333333'::uuid, '施術は痛いですか？', 'ボキボキしない、やさしい施術が中心です。強さは調整できます。', array['痛い', 'ボキボキ']::text[], true, 4),
  ('33333333-3333-4333-8333-000000000005'::uuid, '33333333-3333-4333-8333-333333333333'::uuid, '予約は必要ですか？', '当院は完全予約制です。下のボタンからご予約ください。お電話でも承ります。', array['予約', '完全予約']::text[], true, 5),
  ('33333333-3333-4333-8333-000000000006'::uuid, '33333333-3333-4333-8333-333333333333'::uuid, '支払い方法を教えてください', '現金、クレジットカード、QRコード決済が使えます。', array['支払い', 'カード', '現金', 'QR']::text[], true, 6),
  ('33333333-3333-4333-8333-000000000007'::uuid, '33333333-3333-4333-8333-333333333333'::uuid, 'キャンセル料はかかりますか？', '前日までのご連絡なら無料です。', array['キャンセル', 'キャンセル料']::text[], true, 7);
